package main

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"strings"
	"sync"

	"github.com/klauspost/compress/zstd"
)

// Generated by `make stuffr-wasm`; committed so a plain `go build` works.

//go:embed stuffr/stuffr.wasm.zst
var stuffrWasmZst []byte

//go:embed stuffr/VERSION
var stuffrVersionFile string

//go:embed stuffr/version.json
var stuffrVersionJSON []byte

var (
	stuffrWasmOnce  sync.Once
	stuffrWasmBytes []byte
	stuffrWasmErr   error

	stuffrPersOnce sync.Once
	stuffrPers     map[string]bool
)

// stuffrWasm returns the decompressed stuffr wasm module. The decompression
// happens once; later calls return the same slice (callers must not mutate).
func stuffrWasm() ([]byte, error) {
	stuffrWasmOnce.Do(func() {
		dec, err := zstd.NewReader(nil)
		if err != nil {
			stuffrWasmErr = err
			return
		}
		defer dec.Close()
		stuffrWasmBytes, stuffrWasmErr = dec.DecodeAll(stuffrWasmZst, nil)
	})
	return stuffrWasmBytes, stuffrWasmErr
}

// stuffrVersion returns the trimmed first line of the embedded VERSION file.
func stuffrVersion() string {
	line, _, _ := strings.Cut(stuffrVersionFile, "\n")
	return strings.TrimSpace(line)
}

// stuffrPersonalities returns the argv0 personality names (gzip, unzip,
// zstdcat, ...) from the embedded version.json. Parsed once.
func stuffrPersonalities() map[string]bool {
	stuffrPersOnce.Do(func() {
		stuffrPers = map[string]bool{}
		var v struct {
			Personalities []string `json:"personalities"`
		}
		if err := json.NewDecoder(bytes.NewReader(stuffrVersionJSON)).Decode(&v); err != nil {
			return
		}
		for _, p := range v.Personalities {
			stuffrPers[p] = true
		}
	})
	return stuffrPers
}
